-- SEC EDGAR financials for US-listed employers on the board: 178 companies
-- matched by exact normalized name to SEC's official ticker file (ambiguous
-- brands dropped: Prudential, Wise), with up to 3 fiscal years of revenue and
-- net income from each company's own XBRL filings (10-K, 20-F for foreign
-- filers), values spot-checked for plausibility, stale filers (latest FY
-- before 2023) excluded. Keyed by board-token slug so multi-board companies
-- resolve with one row. Public data, public read.

CREATE TABLE IF NOT EXISTS public.company_financials (
  slug text PRIMARY KEY,
  cik bigint NOT NULL,
  ticker text NOT NULL,
  exchange text NOT NULL DEFAULT '',
  sec_name text NOT NULL DEFAULT '',
  currency text NOT NULL DEFAULT 'USD',
  -- [{fy, revenue, net_income}] newest first, ≤3 entries; nulls where unfiled.
  series jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.company_financials ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "company_financials_public_read" ON public.company_financials;
CREATE POLICY "company_financials_public_read" ON public.company_financials FOR SELECT USING (true);

ON CONFLICT (slug) DO UPDATE
  SET cik = EXCLUDED.cik, ticker = EXCLUDED.ticker, exchange = EXCLUDED.exchange,
      sec_name = EXCLUDED.sec_name, currency = EXCLUDED.currency,
      series = EXCLUDED.series, updated_at = now();

-- One-call lander lookup: the slug of any of a company's board tokens.
CREATE OR REPLACE FUNCTION public.get_company_financials(p_token text)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    (SELECT jsonb_build_object(
       'ticker', f.ticker, 'exchange', f.exchange, 'sec_name', f.sec_name,
       'cik', f.cik, 'currency', f.currency, 'series', f.series)
     FROM public.company_financials f
     WHERE f.slug = split_part(p_token, '~', 1)
     LIMIT 1),
    'null'::jsonb
  );
$$;
GRANT EXECUTE ON FUNCTION public.get_company_financials(text) TO anon, authenticated;

NOTIFY pgrst, 'reload schema';
